
var KalturaKeyManagementPolicyService={get:function(objectType,objectId){var kparams=new Object();kparams.objectType=objectType;kparams.objectId=objectId;return new KalturaRequestBuilder("drm_keymanagementpolicy","get",kparams);},update:function(objectType,objectId,keyManagementPolicy){var kparams=new Object();kparams.objectType=objectType;kparams.objectId=objectId;kparams.keyManagementPolicy=keyManagementPolicy;return new KalturaRequestBuilder("drm_keymanagementpolicy","update",kparams);}}